package cn.sifangguan.hotelaios.finance;
import cn.sifangguan.hotelaios.shared.audit.AuditWriter;
import cn.sifangguan.hotelaios.shared.context.*;
import cn.sifangguan.hotelaios.shared.db.TenantDatabaseContext;
import cn.sifangguan.hotelaios.shared.security.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.zonky.test.db.postgres.embedded.EmbeddedPostgres;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import java.util.function.Supplier;
import static cn.sifangguan.hotelaios.finance.FinanceBusinessExceptionModels.*;
import static org.assertj.core.api.Assertions.*;

class FinanceBusinessExceptionIntegrationTest {
 static EmbeddedPostgres pg;static JdbcTemplate jdbc;static TransactionTemplate tx;static FinanceBusinessExceptionService exceptions;static FinanceBusinessService business;static FinanceAccountingService accounting;
 static final UUID T=UUID.fromString("10000000-0000-0000-0000-000000000001");static final LocalDate DAY=LocalDate.of(2026,10,24);
 UUID owner,finance,director,cashier,hotel,company,batch,entry,proof,policy;
 @BeforeAll static void start()throws Exception{pg=EmbeddedPostgres.builder().start();var ds=pg.getPostgresDatabase();jdbc=new JdbcTemplate(ds);jdbc.execute("create role hotel_ai_os_app nologin nosuperuser nobypassrls");Flyway.configure().dataSource(ds).locations("classpath:db/migration").target("106").load().migrate();var named=new NamedParameterJdbcTemplate(ds);var db=new TenantDatabaseContext(jdbc,true);var access=new AccessPolicy();var mapper=new ObjectMapper().findAndRegisterModules();var audit=new AuditWriter(named,e->{});accounting=new FinanceAccountingService(named,db,access,audit,mapper);business=new FinanceBusinessService(named,db,access,audit,mapper,accounting);exceptions=new FinanceBusinessExceptionService(named,db,access,audit,accounting);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));}
 @AfterAll static void stop()throws Exception{if(pg!=null)pg.close();}
 @AfterEach void clear(){TenantContext.clear();}
 @BeforeEach void seed(){owner=account();finance=account();director=account();cashier=account();hotel=UUID.randomUUID();company=UUID.randomUUID();jdbc.update("insert into org_unit(id,tenant_id,code,name,unit_type) values(?,?,?,'例外测试店','HOTEL')",hotel,T,hotel.toString());jdbc.update("insert into finance_company(id,tenant_id,name,tax_number) values(?,?,'例外测试法人',?)",company,T,company.toString().replace("-",""));jdbc.update("insert into finance_store_config(tenant_id,hotel_id,company_id,manager_account_id,finance_account_id,director_account_id,leader_account_id,cashier_account_id,workflow_version,enabled) values(?,?,?,?,?,?,?,?,2,true)",T,hotel,company,account(),finance,director,account(),cashier);as(owner,"*");}
 @Test void independentBadDebtConsumesOnlyUnpaidReceivableAndNeverRewritesIncomeOrCash(){income(DAY);var input=adjust("60",DAY);call(()->exceptions.adjustment(input));assertThat(unpaid()).isEqualTo("90.00");as(owner,"finance.review");assertThatThrownBy(()->call(()->exceptions.reviewAdjustment(input.requestId(),review(true)))).hasMessageContaining("冻结的独立审核人");as(finance,"finance.review");call(()->exceptions.reviewAdjustment(input.requestId(),review(true)));assertThat(unpaid()).isEqualTo("30.00");assertThat(jdbc.queryForObject("select amount from fb_revenue_entry where id=?",BigDecimal.class,entry)).isEqualByComparingTo("100");assertThat(jdbc.queryForObject("select count(*) from fb_revenue_movement where entry_id=?",Integer.class,entry)).isZero();as(cashier,"finance.pay");assertThatThrownBy(()->call(()->business.moveRevenue(entry,new FinanceBusinessModels.RevenueMovement(UUID.randomUUID(),"RECEIPT",new BigDecimal("31"),DAY,"真实到账","不能重收已核销应收")))).hasMessageContaining("超过结算净额");assertThat(jdbc.queryForObject("select count(*) from fa_source_event where source_type='FB_RECEIVABLE_ADJUSTMENT' and source_id=?",Integer.class,input.requestId())).isOne();assertThatThrownBy(()->jdbc.update("delete from fb_receivable_adjustment where id=?",input.requestId())).hasMessageContaining("immutable");}
 @Test void channelDifferenceHasOriginalProofAndCannotWriteOffSettledFundsOrStaleVersions(){income(DAY);as(cashier,"finance.pay");call(()->business.moveRevenue(entry,new FinanceBusinessModels.RevenueMovement(UUID.randomUUID(),"RECEIPT",new BigDecimal("40"),DAY,"实际到账40","真实银行渠道结算")));as(owner,"*");assertThatThrownBy(()->call(()->exceptions.adjustment(adjust("51",DAY)))).hasMessageContaining("净未清金额");var badProof=new Adjustment(UUID.randomUUID(),entry,1,"CHANNEL_DIFFERENCE",new BigDecimal("10"),DAY,UUID.randomUUID(),finance,"真实差额依据");assertThatThrownBy(()->call(()->exceptions.adjustment(badProof))).hasMessageContaining("真实坏账/渠道差异依据");var input=new Adjustment(UUID.randomUUID(),entry,1,"CHANNEL_DIFFERENCE",new BigDecimal("50"),DAY,proof,finance,"渠道真实扣差已独立核对");call(()->exceptions.adjustment(input));as(cashier,"finance.pay");call(()->business.moveRevenue(entry,new FinanceBusinessModels.RevenueMovement(UUID.randomUUID(),"RECEIPT",BigDecimal.ONE,DAY,"后续真实到账","应收版本已改变")));as(finance,"finance.review");assertThatThrownBy(()->call(()->exceptions.reviewAdjustment(input.requestId(),review(true)))).hasMessageContaining("未清金额已改变");call(()->exceptions.reviewAdjustment(input.requestId(),review(false)));assertThat(unpaid()).isEqualTo("49.00");}
 @Test void adjustmentInNewOpenPeriodPreservesOriginalBusinessDateAndHistoricalAging(){LocalDate old=DAY.minusMonths(1);income(old);UUID book=UUID.randomUUID();as(owner,"*");call(()->accounting.createBook(new FinanceAccountingModels.Book(book,hotel,company,"实际账簿",old.withDayOfMonth(1))));jdbc.update("insert into fa_period(tenant_id,book_id,month,status) values(?,?,?,'CLOSED')",T,book,old.withDayOfMonth(1));assertThatThrownBy(()->call(()->exceptions.adjustment(adjust("20",old)))).hasMessageContaining("已锁定");var input=adjust("20",DAY);call(()->exceptions.adjustment(input));as(finance,"finance.review");call(()->exceptions.reviewAdjustment(input.requestId(),review(true)));assertThat(jdbc.queryForObject("select fb_receivable_adjusted_amount(?,?,?)",BigDecimal.class,T,entry,old)).isZero();assertThat(jdbc.queryForObject("select fb_receivable_adjusted_amount(?,?,?)",BigDecimal.class,T,entry,DAY)).isEqualByComparingTo("20");assertThat(jdbc.queryForObject("select business_date from fb_receivable_adjustment where id=?",java.sql.Date.class,input.requestId())).isEqualTo(java.sql.Date.valueOf(old));}
 @Test void configuredCalendarRequiresIndependentActivationAndRealReceiptsNotMerelyPreparedReturn(){taxPolicy();var in=calendarInput("PAYMENT");call(()->exceptions.createCalendar(in));assertThat(items(call(()->exceptions.calendar())).getFirst()).containsEntry("receiptState","REVIEW");assertThatThrownBy(()->call(()->exceptions.reviewCalendar(in.requestId(),review(true)))).hasMessageContaining("冻结的独立审核人");as(finance,"finance.tax","finance.review");call(()->exceptions.reviewCalendar(in.requestId(),review(true)));assertThat(items(call(()->exceptions.calendar())).getFirst()).containsEntry("receiptState","RETURN_NOT_LINKED").containsEntry("overdue",true);as(owner,"finance.tax");var taxReturn=new FinanceBusinessModels.TaxReturn(UUID.randomUUID(),hotel,"2026-10",policy,new BigDecimal("20"),"真实申报与票账取数的差异说明");call(()->business.createTaxReturn(taxReturn));UUID receipt=original("TAX",taxReturn.requestId());as(finance,"finance.tax","finance.review");var link=new Link(UUID.randomUUID(),taxReturn.requestId(),1,"同主体同税种所属期政策的实际申报取数");call(()->exceptions.link(in.requestId(),link));call(()->exceptions.link(in.requestId(),link));assertThat(items(call(()->exceptions.calendar())).getFirst()).containsEntry("receiptState","FILING_RECEIPT_MISSING");call(()->business.recordTaxReceipt(taxReturn.requestId(),new FinanceBusinessModels.TaxReceipt(UUID.randomUUID(),"FILING","真实申报回执"+UUID.randomUUID(),new BigDecimal("20"),receipt,DAY)));call(()->business.recordTaxReceipt(taxReturn.requestId(),new FinanceBusinessModels.TaxReceipt(UUID.randomUUID(),"PAYMENT","第一笔真实完税"+UUID.randomUUID(),new BigDecimal("5"),receipt,DAY)));assertThat(items(call(()->exceptions.calendar())).getFirst()).containsEntry("receiptState","PAYMENT_RECEIPT_INCOMPLETE");call(()->business.recordTaxReceipt(taxReturn.requestId(),new FinanceBusinessModels.TaxReceipt(UUID.randomUUID(),"PAYMENT","第二笔真实完税"+UUID.randomUUID(),new BigDecimal("15"),receipt,DAY)));assertThat(items(call(()->exceptions.calendar())).getFirst()).containsEntry("receiptState","ACTUAL_PAYMENT_ARCHIVED").containsEntry("actualPaidAmount","20.00").containsEntry("externalExecution","NONE");}
 @Test void calendarDoesNotAcceptUnconfiguredReviewerDuplicateObligationsOrWrongPeriodReturns(){taxPolicy();var in=calendarInput("FILING");call(()->exceptions.createCalendar(in));assertThatThrownBy(()->call(()->exceptions.createCalendar(calendarInput("FILING")))).hasMessageContaining("已有未取消义务");as(finance,"finance.tax","finance.review");call(()->exceptions.reviewCalendar(in.requestId(),review(true)));assertThatThrownBy(()->call(()->exceptions.link(in.requestId(),new Link(UUID.randomUUID(),UUID.randomUUID(),1,"不可链接伪造申报")))).hasMessageContaining("同门店同主体");jdbc.update("update finance_store_config set finance_account_id=? where hotel_id=?",account(),hotel);assertThat(items(call(()->exceptions.calendar())).getFirst()).containsEntry("reviewerCurrentlyConfigured",false).containsEntry("receiptState","REVIEWER_CONFIG_CHANGED");}
 @Test void taxAndReceivableScopesRemainIndependentAndNoPolicyRateOrDeadlineIsInvented(){taxPolicy();as(owner,"finance.read");assertThatThrownBy(()->call(()->exceptions.calendar())).isInstanceOf(AccessDeniedException.class);TenantContext.set(new TenantPrincipal(T,owner,"TEST",Set.of("TEST"),Set.of("finance.tax","finance.read"),Set.of(UUID.randomUUID()),Set.of(),false,UUID.randomUUID()));assertThat(items(call(()->exceptions.calendar()))).isEmpty();assertThat(items(call(()->exceptions.adjustments()))).isEmpty();}
 @Test void mistakenBadDebtRecoveryIsIndependentPartialThenFullAndNeverExceedsSameLoss(){income(DAY);UUID loss=confirmedLoss("60","BAD_DEBT",DAY);assertThat(unpaid()).isEqualTo("30.00");as(owner,"*");var first=recovery(loss,"20",DAY);call(()->exceptions.recovery(first));call(()->exceptions.recovery(first));as(finance,"finance.review");assertThatThrownBy(()->call(()->exceptions.reviewRecovery(first.requestId(),review(true)))).hasMessageContaining("冻结的独立审核人");as(director,"finance.review");call(()->exceptions.reviewRecovery(first.requestId(),review(true)));call(()->exceptions.reviewRecovery(first.requestId(),review(true)));assertThat(unpaid()).isEqualTo("50.00");as(owner,"*");var tail=recovery(loss,"40",DAY);call(()->exceptions.recovery(tail));as(director,"finance.review");call(()->exceptions.reviewRecovery(tail.requestId(),review(true)));assertThat(unpaid()).isEqualTo("90.00");as(owner,"*");assertThatThrownBy(()->call(()->exceptions.recovery(recovery(loss,"0.01",DAY)))).hasMessageContaining("同一原损失尚未恢复");assertThat(jdbc.queryForObject("select amount from fb_receivable_adjustment where id=?",BigDecimal.class,loss)).isEqualByComparingTo("60");assertThat(jdbc.queryForObject("select count(*) from fa_source_event where source_type='FB_RECEIVABLE_RECOVERY' and hotel_id=?",Integer.class,hotel)).isEqualTo(2);assertThatThrownBy(()->jdbc.update("update fb_receivable_recovery set amount=1 where id=?",first.requestId())).hasMessageContaining("immutable");}
 @Test void channelRecoveryRechecksActualReceiptRefundDependenciesAndDoesNotInventNewRevenue(){income(DAY);as(cashier,"finance.pay");call(()->business.moveRevenue(entry,new FinanceBusinessModels.RevenueMovement(UUID.randomUUID(),"RECEIPT",new BigDecimal("40"),DAY,"真实原收款","渠道实收40")));UUID loss=confirmedLoss("50","CHANNEL_DIFFERENCE",DAY);as(owner,"*");var stale=recovery(loss,"50",DAY);call(()->exceptions.recovery(stale));as(cashier,"finance.pay");call(()->business.moveRevenue(entry,new FinanceBusinessModels.RevenueMovement(UUID.randomUUID(),"REFUND",new BigDecimal("10"),DAY,"真实退回款","恢复申请期间实际现金已变化")));as(director,"finance.review");assertThatThrownBy(()->call(()->exceptions.reviewRecovery(stale.requestId(),review(true)))).hasMessageContaining("实际收款/消费核销已改变");call(()->exceptions.reviewRecovery(stale.requestId(),review(false)));as(owner,"*");var real=recovery(loss,"50",DAY);call(()->exceptions.recovery(real));as(director,"finance.review");call(()->exceptions.reviewRecovery(real.requestId(),review(true)));assertThat(unpaid()).isEqualTo("60.00");as(cashier,"finance.pay");call(()->business.moveRevenue(entry,new FinanceBusinessModels.RevenueMovement(UUID.randomUUID(),"RECEIPT",new BigDecimal("60"),DAY,"恢复后真实到账","已恢复原应收实收")));assertThat(unpaid()).isEqualTo("0.00");assertThat(jdbc.queryForObject("select amount from fb_revenue_entry where id=?",BigDecimal.class,entry)).isEqualByComparingTo("100");assertThat(jdbc.queryForObject("select count(*) from fb_revenue_entry where hotel_id=?",Integer.class,hotel)).isOne();}
 @Test void receivableRecoveryAfterClosedPeriodPreservesOldLossAndOriginalBusinessDay(){LocalDate old=DAY.minusMonths(1);income(old);UUID loss=confirmedLoss("20","BAD_DEBT",old),book=UUID.randomUUID();as(owner,"*");call(()->accounting.createBook(new FinanceAccountingModels.Book(book,hotel,company,"恢复真实账簿",old.withDayOfMonth(1))));jdbc.update("insert into fa_period(tenant_id,book_id,month,status) values(?,?,?,'CLOSED')",T,book,old.withDayOfMonth(1));assertThatThrownBy(()->call(()->exceptions.recovery(recovery(loss,"5",old)))).hasMessageContaining("已锁定");var input=recovery(loss,"5",DAY);call(()->exceptions.recovery(input));as(director,"finance.review");call(()->exceptions.reviewRecovery(input.requestId(),review(true)));assertThat(jdbc.queryForObject("select fb_receivable_adjusted_amount(?,?,?)",BigDecimal.class,T,entry,old)).isEqualByComparingTo("20");assertThat(jdbc.queryForObject("select fb_receivable_adjusted_amount(?,?,?)",BigDecimal.class,T,entry,DAY)).isEqualByComparingTo("15");assertThat(jdbc.queryForMap("select business_date,accounting_on from fb_receivable_recovery where id=?",input.requestId())).containsEntry("business_date",java.sql.Date.valueOf(old)).containsEntry("accounting_on",java.sql.Date.valueOf(DAY));}
 @Test void recoveryCannotUseOldReclosedIncomeSnapshotButCanLinkOriginalLossToCurrentRevision(){income(DAY);UUID loss=confirmedLoss("40","BAD_DEBT",DAY);as(owner,"*");var stale=recovery(loss,"10",DAY);call(()->exceptions.recovery(stale));UUID revised=UUID.randomUUID();call(()->business.importRevenue(new FinanceBusinessModels.RevenueImport(revised,hotel,"PMS","真实渠道",DAY,DAY,2,1,new BigDecimal("110"),"真实重结修订",finance,true,List.of(new FinanceBusinessModels.RevenueRow("实际外部订单","AR","真实客户",DAY,new BigDecimal("110"),new BigDecimal("105"),new BigDecimal("5"),new BigDecimal("10"),BigDecimal.ZERO)))));original("REVENUE",revised);as(finance,"finance.review");call(()->business.confirmRevenue(revised,new FinanceBusinessModels.Confirm(UUID.randomUUID(),0,"独立核对重结")));as(director,"finance.review");assertThatThrownBy(()->call(()->exceptions.reviewRecovery(stale.requestId(),review(true)))).hasMessageContaining("来源版本");call(()->exceptions.reviewRecovery(stale.requestId(),review(false)));entry=jdbc.queryForObject("select id from fb_revenue_entry where batch_id=?",UUID.class,revised);as(owner,"*");var real=recovery(loss,"10",DAY);call(()->exceptions.recovery(real));as(director,"finance.review");call(()->exceptions.reviewRecovery(real.requestId(),review(true)));assertThat(unpaid()).isEqualTo("70.00");}
 private UUID confirmedLoss(String value,String kind,LocalDate day){as(owner,"*");UUID loss=UUID.randomUUID();call(()->exceptions.adjustment(new Adjustment(loss,entry,1,kind,new BigDecimal(value),day,proof,finance,"真实原损失独立确认依据")));as(finance,"finance.review");call(()->exceptions.reviewAdjustment(loss,review(true)));as(owner,"*");return loss;}
 private Recovery recovery(UUID loss,String value,LocalDate day){return new Recovery(UUID.randomUUID(),loss,1,new BigDecimal(value),day,proof,director,"原误核销恢复的独立证据，核对现有实收及原损失，不再次确认收入");}
 private void income(LocalDate day){as(owner,"*");batch=UUID.randomUUID();call(()->business.importRevenue(new FinanceBusinessModels.RevenueImport(batch,hotel,"PMS","真实渠道",day,day,1,1,new BigDecimal("100"),"完整真实日结",finance,true,List.of(new FinanceBusinessModels.RevenueRow("实际外部订单", "AR","真实客户",day,new BigDecimal("100"),new BigDecimal("95"),new BigDecimal("5"),new BigDecimal("10"),BigDecimal.ZERO)))));proof=original("REVENUE",batch);as(finance,"finance.review");call(()->business.confirmRevenue(batch,new FinanceBusinessModels.Confirm(UUID.randomUUID(),0,"独立核对来源原件")));entry=jdbc.queryForObject("select id from fb_revenue_entry where batch_id=?",UUID.class,batch);as(owner,"*");}
 private UUID original(String domain,UUID resource){UUID id=UUID.randomUUID();call(()->business.registerAttachment(domain,resource,id,"实际原件.pdf","application/pdf",100,"0".repeat(64),T+"/"+resource+"/"+id+".original","CLEAN"));return id;}
 private void taxPolicy(){as(owner,"*");policy=UUID.randomUUID();call(()->business.createTaxPolicy(new FinanceBusinessModels.TaxPolicy(policy,hotel,"经确认实际政策"+UUID.randomUUID(),1,DAY.withDayOfMonth(1),DAY.withDayOfMonth(31),"财务已核验官方政策依据",List.of(new FinanceBusinessModels.TaxField("OUTPUT","实际销项税额","OUTPUT_TAX",BigDecimal.ONE)))));as(director,"finance.tax","finance.configure");call(()->business.publishTaxPolicy(policy,new FinanceBusinessModels.Confirm(UUID.randomUUID(),1,"独立核验实际政策版本")));as(owner,"*");}
 private FinanceBusinessExceptionModels.Calendar calendarInput(String obligation){return new FinanceBusinessExceptionModels.Calendar(UUID.randomUUID(),hotel,policy,"实际税种","实际申报义务","2026-10",DAY.minusDays(1),obligation,"本期已核验官方日历及延期文件，不预设全国统一截止日",finance);}
 private Adjustment adjust(String value,LocalDate day){return new Adjustment(UUID.randomUUID(),entry,1,"BAD_DEBT",new BigDecimal(value),day,proof,finance,"经核对真实未收余额及坏账依据，不自动作为税前扣除");}
 private Review review(boolean approve){return new Review(0,approve,"独立核对实际依据、来源及本期截止并确认处理");}
 private String unpaid(){as(finance,"finance.read");return items(call(()->business.revenueAccounts())).stream().filter(r->entry.equals(r.get("id"))).findFirst().orElseThrow().get("outstandingAmount").toString();}
 private UUID account(){UUID id=UUID.randomUUID();jdbc.update("insert into user_account(id,tenant_id,login_name,display_name) values(?,?,?,'例外测试人员')",id,T,id.toString());return id;}
 private void as(UUID actor,String...permissions){TenantContext.set(new TenantPrincipal(T,actor,"TEST",Set.of("TEST"),Set.of(permissions),Set.of(hotel),Set.of(),false,UUID.randomUUID()));}
 @SuppressWarnings("unchecked") private List<Map<String,Object>> items(Map<String,Object> data){return (List<Map<String,Object>>)data.get("items");}
 private static <A>A call(Supplier<A> work){return tx.execute(s->{jdbc.execute("set local role hotel_ai_os_app");return work.get();});}
}
